public bool CalculateCircle(Point3d testPoint)
    {
      var rc = false;
      var point = BasePlane.ClosestPoint(testPoint);
      var dir = point - BasePlane.Origin;
      if (!dir.IsTiny())
      {
        Circle = new Circle(BasePlane, dir.Length);
        rc = Circle.IsValid;
      }
      return rc;
    }

