private bool GetLayerPathName(File3dm file, int layerIndex, string delimeter, ref string fullName)
    {
      if (null == file || layerIndex < 0 || layerIndex >= file.AllLayers.Count)
        return false;

      string name = null;
      for (var i = 0; i < file.AllLayers.Count; i++)
      {
        var layer = file.AllLayers.FindIndex(layerIndex);
        var layer_name = layer.Name;
        if (string.IsNullOrEmpty(name))
        {
          name = layer_name;
        }
        else
        {
          var child_name = name;
          name = layer_name;
          if (!string.IsNullOrEmpty(delimeter))
            name += delimeter;
          name += child_name;
        }

        if (layer.ParentLayerId == Guid.Empty)
          break;

        layerIndex = FindLayerFromId(file, layer.ParentLayerId);
        if (layerIndex < 0)
          break;
      }

      fullName = name;

      return true;
    }

